/**
 * Market data + statistics for OMNIM AI.
 *
 * History comes from public sources only:
 *  - US stocks / ETFs: Yahoo Finance daily chart API (the underlying listing, e.g. TSLA for TSLAon)
 *  - Crypto and tokenised gold: CoinGecko daily market_chart
 * Every number the assistant quotes is computed here from those closes, never generated by the model.
 */

export interface Instrument {
  symbol: string; // symbol as listed in OMNIM
  name: string;
  kind: 'stock' | 'etf' | 'gold' | 'crypto';
  source: 'yahoo' | 'coingecko';
  ref: string; // yahoo ticker or coingecko id
}

