export interface Stats {
  symbol: string;
  name: string;
  kind: Instrument['kind'];
  source: string;
  asOf: string;
  price: number;
  ret7d: number | null;
  ret30d: number | null;
  ret90d: number | null;
  ret1y: number | null;
  volAnn: number | null; // annualised volatility of daily returns
  maxDrawdown1y: number | null; // worst peak-to-trough, negative
  pctFrom52wHigh: number | null; // negative when below the high
  trend: 'up' | 'down' | 'mixed' | 'n/a'; // price vs 50d / 200d averages
  score: number | null; // transparent risk-adjusted momentum score, see scoreOf()
  points: number;
}

const FETCH_TIMEOUT = 8000;

async function getJson(url: string): Promise<any> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT);
  try {
    const res = await fetch(url, { signal: ctrl.signal, headers: { Accept: 'application/json' } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } finally {
    clearTimeout(t);
  }
}

/** Daily closes, oldest first. */
async function fetchCloses(i: Instrument): Promise<{ closes: number[]; asOf: string }> {
  if (i.source === 'yahoo') {
    const json = await getJson(
      `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(i.ref)}?range=1y&interval=1d`
    );
    const r = json?.chart?.result?.[0];
    const raw: (number | null)[] = r?.indicators?.quote?.[0]?.close ?? [];
    const ts: number[] = r?.timestamp ?? [];
    const closes = raw.filter((v): v is number => typeof v === 'number' && v > 0);
    if (closes.length < 30) throw new Error('not enough history');
    const last = ts[ts.length - 1];
    return { closes, asOf: last ? new Date(last * 1000).toISOString().slice(0, 10) : '' };
  }
  const json = await getJson(
    `https://api.coingecko.com/api/v3/coins/${i.ref}/market_chart?vs_currency=usd&days=365&interval=daily`
  );
  const prices: [number, number][] = json?.prices ?? [];
  const closes = prices.map((p) => p[1]).filter((v) => typeof v === 'number' && v > 0);
  if (closes.length < 30) throw new Error('not enough history');
  return { closes, asOf: new Date(prices[prices.length - 1][0]).toISOString().slice(0, 10) };
}

const retOver = (c: number[], days: number) => (c.length > days ? c[c.length - 1] / c[c.length - 1 - days] - 1 : null);
const avg = (a: number[]) => a.reduce((s, v) => s + v, 0) / a.length;
const round = (v: number | null, d = 4) => (v === null || !isFinite(v) ? null : Number(v.toFixed(d)));

export function computeStats(i: Instrument, closes: number[], asOf: string): Stats {
  const price = closes[closes.length - 1];
  const logRets = closes.slice(1).map((v, k) => Math.log(v / closes[k]));
  const mean = avg(logRets);
  const sd = Math.sqrt(avg(logRets.map((r) => (r - mean) ** 2)));
  // Stocks trade ~252 days a year, crypto and tokenised gold every day.
  const volAnn = sd * Math.sqrt(i.source === 'yahoo' ? 252 : 365);

  let peak = closes[0];
  let maxDD = 0;
  for (const v of closes) {
    peak = Math.max(peak, v);
    maxDD = Math.min(maxDD, v / peak - 1);
  }
  const high = Math.max(...closes);

  const sma50 = closes.length >= 50 ? avg(closes.slice(-50)) : null;
  const sma200 = closes.length >= 200 ? avg(closes.slice(-200)) : null;
  let trend: Stats['trend'] = 'n/a';
  if (sma50 !== null && sma200 !== null) {
    trend = price > sma50 && sma50 > sma200 ? 'up' : price < sma50 && sma50 < sma200 ? 'down' : 'mixed';
  } else if (sma50 !== null) {
    trend = price > sma50 ? 'up' : 'down';
  }

  const stats: Stats = {
    symbol: i.symbol,
    name: i.name,
    kind: i.kind,
    source: i.source === 'yahoo' ? 'Yahoo Finance' : 'CoinGecko',
    asOf,
    price: round(price, 4)!,
    ret7d: round(retOver(closes, 7)),
    ret30d: round(retOver(closes, 30)),
    ret90d: round(retOver(closes, 90)),
    ret1y: round(retOver(closes, Math.min(closes.length - 1, 364))),
    volAnn: round(volAnn),
    maxDrawdown1y: round(maxDD),
    pctFrom52wHigh: round(price / high - 1),
    trend,
    score: null,
    points: closes.length,
  };
  stats.score = scoreOf(stats);
  return stats;
}

/**
 * Transparent screening score (not a prediction):
 *   90-day return per unit of annualised volatility, +0.25 if the trend is up, -0.25 if down,
 *   minus a penalty for a deep 1-year drawdown beyond -40%.
 * Higher = stronger, steadier recent performance.
 */
export function scoreOf(s: Stats): number | null {
  if (s.ret90d === null || !s.volAnn) return null;
  let score = s.ret90d / s.volAnn;
  if (s.trend === 'up') score += 0.25;
  if (s.trend === 'down') score -= 0.25;
  if (s.maxDrawdown1y !== null && s.maxDrawdown1y < -0.4) score -= (-0.4 - s.maxDrawdown1y) * 1;
  return round(score, 3);
}

let cache: { at: number; data: Stats[]; failed: string[] } | null = null;
let inflight: Promise<{ data: Stats[]; failed: string[]; at: number }> | null = null;
const TTL = 30 * 60 * 1000;

async function build() {
  const data: Stats[] = [];
  const failed: string[] = [];
  const queue = [...UNIVERSE];
  // Small concurrency keeps us inside the free CoinGecko / Yahoo limits.
  const worker = async () => {
    for (let i = queue.shift(); i; i = queue.shift()) {
      // CoinGecko's free tier rate-limits bursts: retry politely with a pause.
      let done = false;
      for (let attempt = 0; attempt < 3 && !done; attempt++) {
        try {
          if (attempt > 0) await new Promise((r) => setTimeout(r, 2500 * attempt));
          const { closes, asOf } = await fetchCloses(i);
          data.push(computeStats(i, closes, asOf));
          done = true;
        } catch {
          /* retry */
        }
      }
      if (!done) failed.push(i.symbol);
    }
  };
  await Promise.all([worker(), worker()]);
  return { data, failed, at: Date.now() };
}

export async function getSnapshot() {
  if (cache && Date.now() - cache.at < TTL) return cache;
  // Stale data beats no data: serve it immediately and refresh behind the scenes.
  if (cache) {
    void refresh().catch(() => {});
    return cache;
  }
  return refresh();
}

function refresh() {
  if (!inflight) {
    inflight = build()
      .then((r) => {
        // Keep the previous good snapshot if this attempt got almost nothing.
        if (r.data.length >= 3) cache = r;
        return cache ?? r; // an empty result is returned but never cached, so the next call retries
      })
      .finally(() => {
        inflight = null;
      });
  }
  return inflight;
}

export function ranked(data: Stats[]) {
  return [...data].filter((s) => s.score !== null).sort((a, b) => b.score! - a.score!);
}
